cd /workspace && python3 - <<'PY'
import sys,random
sys.path.insert(0,'submission')
from crosscheck import CrossCheck
T={'nodes':[{'id':0,'name':'A','external_capacity':10},{'id':1,'name':'B','external_capacity':20}],'links':[{'source':0,'target':1,'capacity':5}],'external_nodes':['A','B']}
S={'trials':1,'epsilon':0,'seed':0,'cutoff':[0,1],'bias':0,'tau':0,'gamma':[1,1],'cache_slots':0}
e=CrossCheck(T);e.replay([],S)
r=random.Random(0)
keys=list(e.counter_capacity)
def val(depth=0):
 choices=['none','bool','int','float','str','list','dict']
 c=r.choice(choices if depth<3 else choices[:5])
 if c=='none':return None
 if c=='bool':return r.choice([True,False])
 if c=='int':return r.randint(-20,20)
 if c=='float':return r.choice([0.0,1.5,-2.3])
 if c=='str':return r.choice(['','x','perturbed','ground_truth','low_A_origination'])
 if c=='list':return [val(depth+1) for _ in range(r.randrange(4))]
 return {r.choice(['x','perturbed','ground_truth','corrected','confidence']):val(depth+1) for _ in range(r.randrange(4))}
for i in range(20000):
 ev={'op':'patch','demands':val(),'counters':val()}
 if r.random()<.7:ev['demands']=[]
 if r.random()<.7:
  cs={}
  for _ in range(r.randrange(5)):cs[r.choice(keys+['bad'])]=val()
  ev['counters']=cs
 if r.random()<.2:ev['extra']=val()
 try:
  out=e._handle_patch(ev)
  assert out.get('op')=='patch' and type(out.get('accepted')) is bool
 except Exception as ex:
  print('EXC',i,ev,repr(ex));break
else:print('no exceptions')
# state should still initial after all invalid/valid random? print
print(e.counter_values,e.demands)
